// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { address __invmut_eoa = address(uint160(0xE0A)); vm.deal(__invmut_eoa, 100 ether); vm.startPrank(__invmut_eoa, __invmut_eoa); c = new PoCGame(address(this), 0); vm.stopPrank(); }
    function testFuzz_property(uint256 a) public {
        a = bound(a, 1, type(uint256).max / 2);
        vm.startPrank(address(uint160(0xE0A)), address(uint160(0xE0A)));
        c.AdjustBetAmounts(a);
        uint256 first = c.currentBetLimit();
        c.AdjustBetAmounts(2 * a);
        uint256 second = c.currentBetLimit();
        vm.stopPrank();
        assertTrue(second == 2 * first);
    }
}
